def tide_time(rooms, links, start, finish):
    times = []
    settled = []
    for room in range(rooms):
        times.append(-1)
        settled.append(False)
    times[start] = 0
    for step in range(rooms):
        here = -1
        for room in range(rooms):
            if settled[room] == False and times[room] >= 0:
                if here < 0 or times[room] < times[here]:
                    here = room
        if here < 0 or here == finish:
            break
        settled[here] = True
        for gate in links:
            if gate[0] == here:
                dest = gate[1]
                period = gate[2]
                phase = gate[3]
                wait = (phase - times[here]) % period
                arrival = times[here] + wait + 1
                if times[dest] < 0 or arrival < times[dest]:
                    times[dest] = arrival
    return times[finish]

